import{_ as e,o as a,c as o,aj as r}from"./chunks/framework.BwH0p-pt.js";const d=JSON.parse('{"title":"First Steps with UnoPim","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/introduction/first-steps.md","filePath":"3.0/introduction/first-steps.md","lastUpdated":1785836850000}'),s={name:"3.0/introduction/first-steps.md"};function i(n,t,l,h,p,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="first-steps-with-unopim" tabindex="-1">First Steps with UnoPim <a class="header-anchor" href="#first-steps-with-unopim" aria-label="Permalink to &quot;First Steps with UnoPim&quot;">​</a></h1><p>Welcome! This page walks you through your first days in UnoPim, in the order that makes each step easier than the last. Every PIM expert started exactly where you are now — with an empty catalog and a login screen.</p><p>Pick the path that matches your role. Many people do both: set up the system first, then build the catalog.</p><h2 id="if-you-administer-unopim" tabindex="-1">If you administer UnoPim <a class="header-anchor" href="#if-you-administer-unopim" aria-label="Permalink to &quot;If you administer UnoPim&quot;">​</a></h2><p>Your job is to prepare the workspace so catalog work can start. Do these steps in order — each one unlocks the next.</p><ol><li><p><strong>Set up your locales</strong> — <a href="./../settings/locale.html">Locales</a></p><p>Locales define the languages your product content will be written in. Do this first, because almost everything you create later — attribute labels, category names, product descriptions — is stored per locale.</p></li><li><p><strong>Add your currencies</strong> — <a href="./../settings/currencies.html">Currencies</a></p><p>Currencies power every price attribute in the catalog. Adding them now means price fields work correctly from the very first product.</p></li><li><p><strong>Create your channels</strong> — <a href="./../settings/channels.html">Channels</a></p><p>A channel is a destination for your product data — a webshop, a marketplace, a print catalog. Channels combine the locales and currencies you just set up, which is why they come third.</p></li><li><p><strong>Invite your team</strong> — <a href="./../settings/users.html">Users</a> and <a href="./../settings/roles.html">Roles</a></p><p>Create a role for each kind of work (catalog manager, viewer, integrator), then invite users into those roles. Setting roles before users means nobody ever has more access than they need.</p></li><li><p><strong>Choose how people sign in</strong> — <a href="./../configuration/microsoft-sso.html">Microsoft SSO</a></p><p>If your company uses Microsoft accounts, connect single sign-on so your team signs in with the account they already have — no extra passwords to manage or reset.</p></li><li><p><strong>Make it yours</strong> — <a href="./../configuration/system-settings.html">System Settings</a></p><p>Upload your logo, set the admin name, and pick sensible defaults. A branded workspace tells your team this is the official home of product data.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Once these six steps are done, the system is ready. Everything after this point is catalog work.</p></div><h2 id="if-you-manage-the-catalog" tabindex="-1">If you manage the catalog <a class="header-anchor" href="#if-you-manage-the-catalog" aria-label="Permalink to &quot;If you manage the catalog&quot;">​</a></h2><p>Product data in UnoPim is built from a few blocks that stack on top of each other. Build them bottom-up and everything fits on the first try.</p><ol><li><p><strong>Create your attributes</strong> — <a href="./../attribute/product-attribute.html">Attributes</a></p><p>Attributes are the individual fields a product can have: name, color, weight, description. They are the smallest building block, so they come first.</p></li><li><p><strong>Organize them into attribute groups</strong> — <a href="./../attribute/attribute-groups.html">Attribute Groups</a></p><p>Groups bundle related attributes (General, Pricing, SEO) so product forms stay tidy. Grouping now saves you from a wall of unsorted fields later.</p></li><li><p><strong>Combine groups into families</strong> — <a href="./../attribute/attribute-family.html">Attribute Families</a></p><p>A family is the full template for one kind of product — a &quot;T-shirt&quot; family carries different fields than a &quot;Laptop&quot; family. Every product you create must belong to a family, which is why families come before products.</p></li><li><p><strong>Build your category tree</strong> — <a href="./../category/categories.html">Categories</a></p><p>Categories organize the catalog the way your shop or team thinks about it. Having the tree ready means each new product can be filed as soon as it is created.</p></li><li><p><strong>Create your first product</strong> — <a href="./../products/simple.html">Simple Products</a></p><p>Now the rewarding part. Pick a family, give the product an SKU, and save. The family you built decides exactly which fields appear on the edit page.</p></li><li><p><strong>Enrich it and watch completeness</strong> — <a href="./../products/">Completeness</a></p><p>Fill in the attributes, add images, and assign categories. The completeness score shows how close the product is to being ready for each channel and locale — your built-in to-do list.</p></li><li><p><strong>Link related products</strong> — <a href="./../associations/">Associations</a></p><p>Connect cross-sells, up-sells, and related items so every sales channel can show &quot;you may also like&quot;. You can even define your own association types.</p></li><li><p><strong>Get data in and out</strong> — <a href="./../data-transfer/import.html">Import</a> and <a href="./../data-transfer/export.html">Export</a></p><p>One product by hand teaches you the model; imports do the volume. Bring in your existing spreadsheet, then export enriched data to wherever it needs to go.</p></li></ol><h2 id="go-further" tabindex="-1">Go further <a class="header-anchor" href="#go-further" aria-label="Permalink to &quot;Go further&quot;">​</a></h2><p>With the basics in place, explore what makes UnoPim 3.0 shine:</p><ul><li><strong>Product variants</strong> — <a href="./../products/configurable.html">Configurable Products</a> and <a href="./../products/variants.html">Variants</a> for products that come in sizes and colors.</li><li><strong>Measurements</strong> — <a href="./../measurements/">Measurement Families</a> give units (kg, cm, liters) to your numeric attributes with automatic conversion.</li><li><strong>Digital Product Passports</strong> — <a href="./../passport/">Passports</a> publish a public compliance page for every product.</li><li><strong>Magic AI</strong> — <a href="./../magic-ai/settings.html">AI Enrichment</a> writes and translates product content for you.</li><li><strong>AI Agent</strong> — <a href="./../ai-agent/ai-agent-chat.html">AI Agent Chat</a> lets you manage the catalog in plain language.</li><li><strong>Filters &amp; saved views</strong> — <a href="./../products/filters-and-views.html">Filters and Views</a> save your favorite grid setups and share them with the team.</li><li><strong>Webhooks &amp; integrations</strong> — <a href="./../configuration/webhooks.html">Webhooks</a> and <a href="./../configuration/integration.html">Integrations</a> keep other systems in sync automatically.</li></ul><p>Take it one step at a time — the order above is the whole secret.</p>',14)])])}const m=e(s,[["render",i]]);export{d as __pageData,m as default};
